// Function to test
function rollDice(): number {
  return Math.floor(Math.random() * 6) + 1;
}

// Jest tests
describe('rollDice', () => {
  afterEach(() => {
    jest.restoreAllMocks();
  });

  test('should return 1 when Math.random returns 0', () => {
    const spy = jest.spyOn(Math, 'random').mockReturnValue(0);

    expect(rollDice()).toBe(1);
    expect(spy).toHaveBeenCalledTimes(1);
  });

  test('should return 6 when Math.random returns just under 1', () => {
    jest.spyOn(Math, 'random').mockReturnValue(0.999);

    expect(rollDice()).toBe(6);
  });

  test('should return 4 for a mid-range random value', () => {
    jest.spyOn(Math, 'random').mockReturnValue(0.5);

    expect(rollDice()).toBe(4);
  });

  test('should use the real Math.random after restoreAllMocks', () => {
    const result = rollDice();

    expect(result).toBeGreaterThanOrEqual(1);
    expect(result).toBeLessThanOrEqual(6);
  });
});

description.en:
Write unit tests for a `parseConfig` function that validates a plain object and throws descriptive errors for invalid input. Use Jest's `toThrow` matcher to verify both that an error is thrown and what its message says.

**Requirements:**
- Test the happy path where valid config is returned unchanged
- Test that missing `port` throws an error containing 'port'
- Test that a non-numeric `port` throws a different, specific error message
- Use `toThrow()` with no arguments, with a string (substring match), and with a regex - show the difference
- Cover at least 4 test cases

**Function signature:**
typescript
interface Config {
  port: number;
  host: string;
}

function parseConfig(input: Record<string, unknown>): Config {
  if (input.port === undefined) throw new Error('Missing required field: port');
  if (typeof input.port !== 'number') throw new Error('Invalid type for port: expected number');
  if (typeof input.host !== 'string' || input.host.length === 0) {
    throw new Error('Missing required field: host');
  }
  return { port: input.port, host: input.host };
}


**Example inputs/outputs:**
- parseConfig({ port: 3000, host: 'localhost' }) → { port: 3000, host: 'localhost' }
- parseConfig({ host: 'localhost' }) → throws Error('Missing required field: port')
- parseConfig({ port: '3000', host: 'localhost' }) → throws Error('Invalid type for port: expected number')

**Edge cases:**
- `host` is an empty string (should still throw, not just missing)
- `port` is `0` (a valid, falsy number - must not be treated as missing)
- Calling the function inside `expect()` must wrap it in an arrow function, not invoke it directly

