interface Config {
  port: number;
  host: string;
}

function parseConfig(input: Record<string, unknown>): Config {
  if (input.port === undefined) throw new Error('Missing required field: port');
  if (typeof input.port !== 'number') throw new Error('Invalid type for port: expected number');
  if (typeof input.host !== 'string' || input.host.length === 0) {
    throw new Error('Missing required field: host');
  }
  return { port: input.port, host: input.host };
}

// Jest tests
describe('parseConfig', () => {
  test('should return parsed config for valid input', () => {
    expect(parseConfig({ port: 3000, host: 'localhost' })).toEqual({
      port: 3000,
      host: 'localhost',
    });
  });

  test('should throw any error when port is missing', () => {
    expect(() => parseConfig({ host: 'localhost' })).toThrow();
  });

  test('should throw a message containing "port" when port is missing', () => {
    expect(() => parseConfig({ host: 'localhost' })).toThrow('port');
  });

  test('should throw a distinct message when port has wrong type', () => {
    expect(() => parseConfig({ port: '3000', host: 'localhost' })).toThrow(
      /invalid type for port/i
    );
  });

  test('should throw when host is an empty string', () => {
    expect(() => parseConfig({ port: 3000, host: '' })).toThrow('host');
  });

  test('should accept port 0 as a valid, non-missing value', () => {
    expect(parseConfig({ port: 0, host: 'localhost' })).toEqual({
      port: 0,
      host: 'localhost',
    });
  });
});

description.en:
Write a snapshot test for a `formatInvoice` function that transforms raw order data into a structured, display-ready object. Use Jest's `toMatchSnapshot()` to catch unintended changes to the output shape.

**Requirements:**
- Write one snapshot test for a typical invoice
- Write one snapshot test for an invoice with an empty items list (a distinct, meaningful shape - not just a variation of the same snapshot)
- Explain in a code comment when a snapshot should be updated (`--updateSnapshot`) versus when a failing snapshot indicates a real regression
- Also include one regular (non-snapshot) assertion on `total`, to show snapshot and explicit assertions can complement each other

**Function signature:**
typescript
interface OrderItem {
  name: string;
  price: number;
  quantity: number;
}

function formatInvoice(items: OrderItem[]): {
  lines: string[];
  total: number;
} {
  const lines = items.map(
    (item) => `${item.name} x${item.quantity} - $${(item.price * item.quantity).toFixed(2)}`
  );
  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  return { lines, total: Number(total.toFixed(2)) };
}


**Example inputs/outputs:**
- formatInvoice([{ name: 'Widget', price: 9.99, quantity: 2 }]) → { lines: ['Widget x2 - $19.98'], total: 19.98 }
- formatInvoice([]) → { lines: [], total: 0 }

**Edge cases:**
- Empty items array
- Single item with quantity 1
- Prices with rounding (e.g. 0.1 + 0.2 style floating point sums)

