function startCountdown(callback: () => void, delayMs: number): void {
  setTimeout(callback, delayMs);
}

// Jest tests
describe('startCountdown', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test('should not call callback before delay has passed', () => {
    const callback = jest.fn();
    startCountdown(callback, 1000);

    jest.advanceTimersByTime(999);

    expect(callback).not.toHaveBeenCalled();
  });

  test('should call callback after delay has passed', () => {
    const callback = jest.fn();
    startCountdown(callback, 1000);

    jest.advanceTimersByTime(1000);

    expect(callback).toHaveBeenCalledTimes(1);
  });

  test('should call callback exactly once even after extra time passes', () => {
    const callback = jest.fn();
    startCountdown(callback, 1000);

    jest.advanceTimersByTime(5000);

    expect(callback).toHaveBeenCalledTimes(1);
  });

  test('should call callback after two smaller time advances summing to the delay', () => {
    const callback = jest.fn();
    startCountdown(callback, 1000);

    jest.advanceTimersByTime(600);
    expect(callback).not.toHaveBeenCalled();

    jest.advanceTimersByTime(400);
    expect(callback).toHaveBeenCalledTimes(1);
  });
});

description.en:
Write unit tests for a `ShoppingCart` class with no external dependencies. Focus on testing behavior through the public API and verifying that internal state changes correctly across a sequence of method calls.

**Requirements:**
- Create a fresh `ShoppingCart` instance in `beforeEach` so tests don't share state
- Test `addItem` increases the total correctly
- Test `removeItem` decreases the total and removes the item if quantity reaches zero
- Test `getTotal` after a sequence of multiple `addItem`/`removeItem` calls
- Test that removing an item not in the cart does not throw and does not change the total
- Cover at least 4 test cases

**Class interface:**
typescript
class ShoppingCart {
  private items: Map<string, { price: number; quantity: number }> = new Map();

  addItem(name: string, price: number, quantity: number = 1): void {
    const existing = this.items.get(name);
    if (existing) {
      existing.quantity += quantity;
    } else {
      this.items.set(name, { price, quantity });
    }
  }

  removeItem(name: string, quantity: number = 1): void {
    const existing = this.items.get(name);
    if (!existing) return;
    existing.quantity -= quantity;
    if (existing.quantity <= 0) {
      this.items.delete(name);
    }
  }

  getTotal(): number {
    let total = 0;
    for (const { price, quantity } of this.items.values()) {
      total += price * quantity;
    }
    return Number(total.toFixed(2));
  }

  getItemCount(): number {
    return this.items.size;
  }
}


**Example inputs/outputs:**
- cart.addItem('Book', 10, 2); cart.getTotal() → 20
- cart.addItem('Book', 10, 2); cart.removeItem('Book', 1); cart.getTotal() → 10
- cart.addItem('Book', 10, 1); cart.removeItem('Book', 1); cart.getItemCount() → 0

**Edge cases:**
- Removing more of an item than is currently in the cart
- Removing an item name that was never added
- Adding the same item name twice (quantities should accumulate, not overwrite)

