import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ThemeContext } from './ThemeContext';
import { ThemedButton } from './ThemedButton';

function renderWithTheme(
  ui: React.ReactElement,
  { theme, toggleTheme = jest.fn() }: { theme: 'light' | 'dark'; toggleTheme?: () => void }
) {
  const utils = render(
    <ThemeContext.Provider value={{ theme, toggleTheme }}>{ui}</ThemeContext.Provider>
  );
  return {
    ...utils,
    toggleTheme,
    rerenderWithTheme: (nextTheme: 'light' | 'dark', nextToggle: () => void = toggleTheme) =>
      utils.rerender(
        <ThemeContext.Provider value={{ theme: nextTheme, toggleTheme: nextToggle }}>
          {ui}
        </ThemeContext.Provider>
      ),
  };
}

describe('ThemedButton', () => {
  test('renders correctly for the light theme', () => {
    renderWithTheme(<ThemedButton />, { theme: 'light' });

    const button = screen.getByRole('button', { name: 'Switch to dark' });
    expect(button).toHaveClass('light-button');
  });

  test('renders correctly for the dark theme', () => {
    renderWithTheme(<ThemedButton />, { theme: 'dark' });

    const button = screen.getByRole('button', { name: 'Switch to light' });
    expect(button).toHaveClass('dark-button');
  });

  test('clicking the button calls toggleTheme exactly once', async () => {
    const user = userEvent.setup();
    const { toggleTheme } = renderWithTheme(<ThemedButton />, { theme: 'light' });

    await user.click(screen.getByRole('button'));

    expect(toggleTheme).toHaveBeenCalledTimes(1);
  });

  test('rerendering with a new theme value updates the button without remounting', () => {
    const { rerenderWithTheme } = renderWithTheme(<ThemedButton />, { theme: 'light' });

    expect(screen.getByRole('button', { name: 'Switch to dark' })).toHaveClass('light-button');

    rerenderWithTheme('dark');

    expect(screen.getByRole('button', { name: 'Switch to light' })).toHaveClass('dark-button');
  });
});

