import { render, screen, cleanup } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { SearchBox } from './SearchBox';

describe('SearchBox debounce', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });

  afterEach(() => {
    jest.useRealTimers();
  });

  test('does not call onSearch immediately after typing', async () => {
    const onSearch = jest.fn();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
    render(<SearchBox onSearch={onSearch} />);

    await user.type(screen.getByRole('searchbox'), 're');

    expect(onSearch).not.toHaveBeenCalled();

    jest.advanceTimersByTime(300);
    expect(onSearch).toHaveBeenCalledWith('re');
  });

  test('typing more characters before the delay resets the timer', async () => {
    const onSearch = jest.fn();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
    render(<SearchBox onSearch={onSearch} />);
    const input = screen.getByRole('searchbox');

    await user.type(input, 'r');
    jest.advanceTimersByTime(100);
    await user.type(input, 'e');
    jest.advanceTimersByTime(100);

    expect(onSearch).not.toHaveBeenCalled();

    jest.advanceTimersByTime(200);
    expect(onSearch).toHaveBeenCalledTimes(1);
    expect(onSearch).toHaveBeenCalledWith('re');
  });

  test('calls onSearch exactly once per burst of typing', async () => {
    const onSearch = jest.fn();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
    render(<SearchBox onSearch={onSearch} />);

    await user.type(screen.getByRole('searchbox'), 'react');
    jest.advanceTimersByTime(300);

    expect(onSearch).toHaveBeenCalledTimes(1);
    expect(onSearch).toHaveBeenCalledWith('react');
  });

  test('respects a custom debounceMs prop', async () => {
    const onSearch = jest.fn();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
    render(<SearchBox onSearch={onSearch} debounceMs={100} />);

    await user.type(screen.getByRole('searchbox'), 'ts');
    jest.advanceTimersByTime(99);
    expect(onSearch).not.toHaveBeenCalled();

    jest.advanceTimersByTime(1);
    expect(onSearch).toHaveBeenCalledWith('ts');
  });

  test('unmounting before the delay elapses never calls onSearch', async () => {
    const onSearch = jest.fn();
    const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
    const { unmount } = render(<SearchBox onSearch={onSearch} />);

    await user.type(screen.getByRole('searchbox'), 'x');
    unmount();
    jest.advanceTimersByTime(1000);

    expect(onSearch).not.toHaveBeenCalled();
  });
});

